export function Timeout({
  timedOut = {{timedOut}},
  timeoutMs = {{timeoutMs}},
  action = "{{action}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa" }}>
      <div style={{ position: "relative", height: 10, background: "#24143014", borderRadius: 999 }}>
        <span style={{ display: "block", height: "100%", width: timedOut ? "100%" : "55%", borderRadius: 999, background: timedOut ? "#241430" : accent }} />
        <span style={{ position: "absolute", right: 0, top: -18, fontSize: 10, opacity: .6 }}>{timeoutMs}ms limit</span>
      </div>
      <p role="status" aria-live="polite" style={{ margin: "14px 0 0", fontWeight: 600, color: "#241430" }}>
        {timedOut ? `The ${action} exceeded ${timeoutMs}ms and was cancelled.` : `Within the ${timeoutMs}ms limit \u2014 still waiting.`}
      </p>
    </div>
  );
}
